import { v2 as cloudinary } from 'cloudinary';

interface IUploadPdfParams {
  fileBase64: string;
  fileName: string;
}

interface IUploadPdfResult {
  publicId: string;
  fileSize?: number;
}

interface ICloudinaryConfig {
  cloudName: string;
  apiKey: string;
  apiSecret: string;
}

function configureCloudinary(): ICloudinaryConfig {
  const cloudName = process.env.CLOUDINARY_CLOUD_NAME;
  const apiKey = process.env.CLOUDINARY_API_KEY;
  const apiSecret = process.env.CLOUDINARY_API_SECRET;

  if (!cloudName || !apiKey || !apiSecret) {
    throw new Error('Cloudinary environment variables are not configured');
  }

  cloudinary.config({
    cloud_name: cloudName,
    api_key: apiKey,
    api_secret: apiSecret,
  });

  return { cloudName, apiKey, apiSecret };
}

/**
 * Exams are uploaded as `resource_type: 'image'` (Cloudinary's PDF handling
 * lives under `image`, not `raw`) with `type: 'authenticated'` so the file is
 * never reachable by a guessable/public URL — every download must go through
 * `generateSignedExamFileUrl`, which is only called after the requester
 * already passed the exam-access authorization check.
 *
 * `raw` was tried first but had to be abandoned: this Cloudinary account
 * forces `Content-Disposition: attachment` on every `raw` delivery — via the
 * `/download` endpoint *and* the plain signed CDN URL, even with
 * `fl_attachment:false` — so the PDF always downloads instead of rendering
 * inline, no matter what URL options are passed. `image` delivery has no such
 * restriction and returns a plain `Content-Type: application/pdf` with no
 * forced disposition.
 */
export async function uploadPdfToCloudinary({
  fileBase64,
  fileName,
}: IUploadPdfParams): Promise<IUploadPdfResult> {
  configureCloudinary();

  const uploadFolder = process.env.CLOUDINARY_UPLOAD_FOLDER || 'minha-vez-app';
  const cleanBase64 = fileBase64.includes(',')
    ? fileBase64.split(',')[1]
    : fileBase64;

  const result = await cloudinary.uploader.upload(
    `data:application/pdf;base64,${cleanBase64}`,
    {
      resource_type: 'image',
      type: 'authenticated',
      folder: `${uploadFolder}/exams`,
      format: 'pdf',
      context: { original_filename: fileName },
    },
  );

  return {
    publicId: result.public_id,
    fileSize: result.bytes,
  };
}

/**
 * Uses the authenticated download endpoint (`api.cloudinary.com/.../download`,
 * generated by `private_download_url`) rather than a plain signed delivery
 * URL so access is time-limited via `expires_at`. Since the asset is
 * `resource_type: 'image'` and we don't pass `attachment: true`, the
 * response has no `Content-Disposition: attachment` header, so the same URL
 * renders inline in a browser/WebView *and* works for downloading — unlike
 * `resource_type: 'raw'`, which this account always forces to download
 * regardless of URL options (see the comment on `uploadPdfToCloudinary`).
 * `expires_at` makes it genuinely short-lived; it's regenerated fresh on
 * every `GET /exams/:id`, only after the caller already passed the
 * exam-access authorization check, and never persisted.
 */
export function generateSignedExamFileUrl(
  publicId: string,
  expiresInSeconds = 10 * 60,
): string {
  configureCloudinary();

  return cloudinary.utils.private_download_url(publicId, 'pdf', {
    resource_type: 'image',
    type: 'authenticated',
    expires_at: Math.floor(Date.now() / 1000) + expiresInSeconds,
  });
}
